#!/usr/bin/env node
/**
 * Build-time generator: reads the local accounts registry SSOT and writes
 * src/types/accounts-generated.ts so the frontend dropdown reflects this
 * server's actual accounts (sahori/kurt on partner, engelmann/office/gmail/
 * werking on dev). The generated file is .gitignored.
 *
 * Resolution order for the registry:
 *   1. CUI_ACCOUNTS_REGISTRY env var (explicit override)
 *   2. ~/.claude/accounts/registry.json   (root → /root/..., partner build user)
 *   3. /home/claude-user/.claude/accounts/registry.json
 *      (partner post-receive runs as root but reads claude-user's registry)
 *
 * If no registry is found, writes a minimal stub (auto + local only) so the
 * build keeps working — the dropdown will show no specific accounts, which
 * is honest about "we don't know yet".
 */
const fs = require('fs');
const path = require('path');

const TARGET = path.resolve(__dirname, '..', 'src', 'types', 'accounts-generated.ts');

// Canonical registry location matches server runtime resolution in
// server/config/paths.ts: process.env.CUI_CLAUDE_USER_HOME || '/home/claude-user'.
const claudeUserHome = process.env.CUI_CLAUDE_USER_HOME || '/home/claude-user';
const candidatePaths = [
  process.env.CUI_ACCOUNTS_REGISTRY,
  path.join(claudeUserHome, '.claude/accounts/registry.json'),
].filter(Boolean);

let registry = null;
let chosenPath = null;
for (const p of candidatePaths) {
  if (fs.existsSync(p)) {
    try {
      registry = JSON.parse(fs.readFileSync(p, 'utf8'));
      chosenPath = p;
      break;
    } catch (err) {
      console.warn(`[generate-accounts] Failed to parse ${p}: ${err.message}`);
    }
  }
}

const PREFIX = [{ id: 'auto', label: 'Auto (Best)', color: '#22c55e' }];
const SUFFIX = [{ id: 'local', label: 'Lokal', color: '#e0af68' }];

const fromRegistry = (registry?.accounts || []).map((a) => ({
  id: a.id,
  label: a.display_name || a.id,
  color: a.color || '#9ece6a',
}));

const accounts = [...PREFIX, ...fromRegistry, ...SUFFIX];

const banner = `// AUTO-GENERATED by scripts/generate-accounts.cjs — DO NOT EDIT.
// Source: ${chosenPath || '(no registry found — stub only)'}
// Regenerate via: npm run generate:accounts (or any build).
`;

const body = `import type { Account } from './index';

export const GENERATED_ACCOUNTS: Account[] = ${JSON.stringify(accounts, null, 2)};
`;

fs.mkdirSync(path.dirname(TARGET), { recursive: true });
fs.writeFileSync(TARGET, banner + '\n' + body, 'utf8');
console.log(`[generate-accounts] Wrote ${accounts.length} accounts to ${TARGET}` +
  (chosenPath ? ` (from ${chosenPath})` : ' (stub — no registry)'));
